@contextmanager
def transaction(conn):
    conn.begin()                 # setup
    try:
        yield conn               # body runs here
        conn.commit()            # teardown: success path
    except BaseException:
        conn.rollback()          # teardown: failure path
        raise                    # never swallow the body's exception

